class Solution:
    def pluck(self, root):
        stack = [(root, 0)]
        smallest_value = float("inf")
        smallest_index = float("inf")

        while stack:
            current_node, current_index = stack.pop()
            if current_node is None:
                continue

            if current_node.value % 2 == 0:
                if current_node.value < smallest_value or (current_node.value == smallest_value and current_index < smallest_index):
                    smallest_value = current_node.value
                    smallest_index = current_index

            if current_node.right:
                stack.append((current_node.right, current_index + 1))
            if current_node.left:
                stack.append((current_node.left, current_index + 1))

        if smallest_value == float("inf"):
            return []
        else:
            return [smallest_value, smallest_index]
