def is_multiply_prime(n):
    def is_prime(num):
        """Helper function to check if a number is prime."""
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def find_factors(num, i):
        """Recursive function to find prime factors of a number."""
        if num == 1:
            return True
        if not is_prime(i):
            return False
        while num % i == 0:
            if not find_factors(num // i, i):
                return False
            num //= i
        return True

    return find_factors(n, 2)

# Example usage:
