class Solution:
    def minPath(self, grid, k):
        import heapq
        from collections import defaultdict

        m = len(grid)
        n = len(grid[0])
        visited = set()
        stack = []

        # Add all starting cells to the heap
        for i in range(m):
            for j in range(n):
                heapq.heappush(stack, (grid[i][j], i, j, k))

        while stack:
            val, i, j, k = heapq.heappop(stack)
            if (i, j) in visited or k == 0:
                continue
            visited.add((i, j))
            if k == 1:
                return [val]

            # Explore all neighbors
            for x, y in [(i+1, j), (i-1, j), (i, j+1), (i, j-1)]:
                if 0 <= x < m and 0 <= y < n:
                    heapq.heappush(stack, (grid[x][y], x, y, k-1))

        return None
```

### 解题思路
#### 其实这个题目就是，根据任意一个位置A和一个长度k，找一个长度为k的路径使得路径的值最小
#### 既然是找最小值，那就想到DP，首先我们要确定dp[i][j][k]的含义
#### dp[i][j][k]表示走到[i,j]处，用k步所走的最小值
#### 这个dp的初始化是，dp[i][j][1] 为 grid[i][j], 当k>1的时候，只要k>1, 那么dp[i][j][k] = min(dp[i-1][j],dp[i+1][j],dp[i][j-1],dp[i][j+1])+grid[i][j] 
#### 最后我们的起点就是dp[0][0][k], 但是因为我们无法确定从哪开始，所以我们就把dp[i][j][k]的值更新为0，把dp[0][0][k]的值更新为grid[0][0]
#### 最后因为dp矩阵是变化的，所以在赋值的时候需要再赋值一次

### 代码

```python3
class Solution:
    def minPath(self, grid: List[List[int]], k: int) -> List[int]:
        m,n = len(grid),len(grid[0])
        dp = [[[0]*k for _ in range(n)] for _ in range(m)]
        for i in range(m):
            for j in range(n):
                dp[i][j][1] = grid[i][j]
        for i in range(m):
            for j in range(n):
                for k in range(2,k+1):
                    if i-1>=0:dp[i][j][k] = min(dp[i-1][j][k],dp[i+1][j][k],dp[i][j-1][k],dp[i][j+1][k])+grid[i][j]
                    if j-1>=0:dp[i][j][k] = min(dp[i][j-1][k],dp[i][j+1][k],dp[i-1][j][k],dp[i][j][k-1])+grid[i][j]
                    if i+1<m:dp[i][j][k] = min(dp[i-1][j][k],dp[i+1][j][k],dp[i][j-1][k],dp[i][j+1][k])+grid[i][j]
                    if j+1<n:dp[i][j][k] = min(dp[i-1][j][k],dp[i+1][j][k],dp[i][j-1][k],dp[i][j+1][k])+grid[i][j]
        res = [grid[0][0]]
        for i in range(m):
            for j in range(n):
                for k in range(k,0,-1):
                    if dp[i][j][k] == grid[i][j]:
                        if k == 1: break
                        else:
                            res.append(grid[i][j])
                            k -= 1
                            i,j = i+k-1,j+k-1
                            break
                break
        return res[::-1]
```

