def tribonacci(n):
    # Define a helper function to compute the sequence up to a given index
    def helper(index, prev2, prev1, current):
        # Base case: if the index is 0, return the current value
        if index == 0:
            return [current]
        # Recursive case: compute the next value and add it to the sequence
        next_value = 1 + current / 2 if current % 2 == 0 else prev2 + prev1 + current
        return helper(index - 1, prev1, current, next_value)

    # Call the helper function starting with the initial values
    return helper(n, 3, 2, 3)

